// FUNCTION: BFME2 0x001A4BF0 size=283 name=?Set_Animation@Animatable3DObjClass@@UAEXPAVHAnimClass@@MH@Z evidence=N:ledger tier=B hypothesis:cohesion
void Animatable3DObjClass::Set_Animation(HAnimClass *motion, float frame, int anim_mode)
{
	// BFME 2 numbers the modes manual, loop, once, ping-pong, clamp to frame, loop backwards, once backwards.
	enum { ANIM_MODE_CLAMP_TO_FRAME = 4, ANIM_MODE_LOOP_BACKWARDS = 5 };

	if (motion != 0) {
		// Add_Ref before the release, in case it is the animation already playing.
		motion->Add_Ref();
		Release();

		CurMotionMode = MOTION_SINGLE;
		ModeAnim.Motion = motion;

		ModeAnim.PrevFrame = MAX(MIN((float)(ModeAnim.Motion->Get_Num_Frames() - 1), frame), 0.0f);

		if (anim_mode == ANIM_MODE_CLAMP_TO_FRAME) {
			// Frame is left alone: the direction says which way to walk toward the target frame.
			if (ModeAnim.PrevFrame >= ModeAnim.Frame) {
				ModeAnim.AnimDirection = 1.0f;
			} else {
				ModeAnim.AnimDirection = -1.0f;
			}
		} else {
			ModeAnim.Frame = frame;
			if (anim_mode < ANIM_MODE_LOOP_BACKWARDS) {
				ModeAnim.AnimDirection = 1.0f;
			} else {
				ModeAnim.AnimDirection = -1.0f;
			}
		}

		ModeAnim.LastSyncTime = WW3D::Get_Sync_Time();
		ModeAnim.FrameRateMultiplier = 1.0f;
		ModeAnim.AnimMode = anim_mode;
	} else {
		Release();
		CurMotionMode = MOTION_BASE_POSE;
	}

	IsTreeValid = false;
}


