bool Animatable3DObjClass::Simple_Evaluate_Bone(int boneindex, float frame, Matrix3D *tm) const
{
	bool retval = false;

	//
	//	Only do this for simple animations
	//
	if (HTree != NULL) {
		
		if (CurMotionMode == MOTION_SINGLE) {
			retval = HTree->Simple_Evaluate_Pivot (ModeAnim.Motion, boneindex, frame, Get_Transform (), tm);
		} else if (CurMotionMode == MOTION_NONE || CurMotionMode == MOTION_BASE_POSE) {
			retval = HTree->Simple_Evaluate_Pivot (boneindex, Get_Transform (), tm);
		} else {
			*tm = Transform;
		}

	} else {
		*tm = Transform;
	}

	return retval;
}

// FUNCTION: BFME2 0x001A5020 size=740 name=?Compute_Current_Frame@Animatable3DObjClass@@IBEMPAM@Z evidence=N:ledger tier=B hypothesis:cohesion
float Animatable3DObjClass::Compute_Current_Frame(float *newDirection) const
{
	// BFME 2 inserts clamp-to-frame before the backwards modes; PrevFrame holds its target.
	enum { ANIM_MODE_LOOP_PINGPONG = 3, ANIM_MODE_CLAMP_TO_FRAME = 4, ANIM_MODE_LOOP_BACKWARDS = 5, ANIM_MODE_ONCE_BACKWARDS = 6 };
	float frame = 0;
	float direction = ModeAnim.AnimDirection;

	switch (CurMotionMode) {
	case MOTION_SINGLE:
		frame = ModeAnim.Frame;

		// Compute the current frame based on elapsed time.
		if (ModeAnim.AnimMode != ANIM_MODE_MANUAL) {
			float sync_time_diff = WW3D::Get_Sync_Time() - ModeAnim.LastSyncTime;
			float delta = ModeAnim.Motion->Get_Frame_Rate() * ModeAnim.FrameRateMultiplier * ModeAnim.AnimDirection * sync_time_diff * 0.001f;
			frame += delta;

			// Wrap the frame.
			switch (ModeAnim.AnimMode) {
			case ANIM_MODE_ONCE:
				if (frame >= ModeAnim.Motion->Get_Num_Frames() - 1) {
					frame = ModeAnim.Motion->Get_Num_Frames() - 1;
				}
				break;
			case ANIM_MODE_LOOP:
				if (frame >= ModeAnim.Motion->Get_Num_Frames() - 1) {
					frame -= ModeAnim.Motion->Get_Num_Frames() - 1;
				}
				// If it is still too far out, reset.
				if (frame >= ModeAnim.Motion->Get_Num_Frames() - 1) {
					frame = 0;
				}
				break;
			case ANIM_MODE_ONCE_BACKWARDS:
				if (frame < 0) {
					frame = 0;
				}
				break;
			case ANIM_MODE_LOOP_BACKWARDS:
				if (frame < 0) {
					frame += ModeAnim.Motion->Get_Num_Frames() - 1;
				}
				// If it is still too far out, reset.
				if (frame < 0) {
					frame = ModeAnim.Motion->Get_Num_Frames() - 1;
				}
				break;
			case ANIM_MODE_LOOP_PINGPONG:
				if (ModeAnim.AnimDirection >= 1.0f) {
					// Playing forwards: reverse direction at the end.
					if (frame >= (ModeAnim.Motion->Get_Num_Frames() - 1)) {
						// Step backwards by the excess time.
						frame = (ModeAnim.Motion->Get_Num_Frames() - 1) * 2 - frame;
						// If it is still too far out, reset.
						if (frame >= ModeAnim.Motion->Get_Num_Frames() - 1) {
							frame = (ModeAnim.Motion->Get_Num_Frames() - 1);
						}
						direction = ModeAnim.AnimDirection * -1.0f;
					}
				} else {
					// Playing backwards: reverse direction at the start.
					if (frame < 0) {
						// Step forwards by the excess time.
						frame = -frame;
						// If it is still too far out, reset.
						if (frame >= ModeAnim.Motion->Get_Num_Frames() - 1) {
							frame = 0;
						}
						direction = ModeAnim.AnimDirection * -1.0f;
					}
				}
				break;
			case ANIM_MODE_CLAMP_TO_FRAME:
				if (ModeAnim.AnimDirection > 0.0f) {
					if (frame > ModeAnim.PrevFrame) frame = ModeAnim.PrevFrame;
				} else {
					if (frame < ModeAnim.PrevFrame) frame = ModeAnim.PrevFrame;
				}
				break;
			}
		}
		break;
	}

	if (newDirection) {
		*newDirection = direction;
	}
	return frame;
}


// FUNCTION: BFME2 0x001A5320 size=51 name=?Single_Anim_Progress@Animatable3DObjClass@@IAEXXZ evidence=N:ledger tier=B hypothesis:cohesion
void Animatable3DObjClass::Single_Anim_Progress(void)
{
	if (CurMotionMode == MOTION_SINGLE) {
		ModeAnim.Frame = Compute_Current_Frame(&ModeAnim.AnimDirection);
		ModeAnim.LastSyncTime = WW3D::Get_Sync_Time();
		IsTreeValid = false;
	}
}

// FUNCTION: BFME2 0x001A5360 size=117 name=?Is_Animation_Complete@Animatable3DObjClass@@UBE_NXZ evidence=N:ledger tier=B hypothesis:cohesion
bool Animatable3DObjClass::Is_Animation_Complete(void) const
{
	if (CurMotionMode == MOTION_SINGLE) {
		if (ModeAnim.AnimMode == 2) {
			return ModeAnim.Frame == (float)(ModeAnim.Motion->Get_Num_Frames() - 1);
		}
		if (ModeAnim.AnimMode == 6) {
			return ModeAnim.Frame == 0.0f;
		}
		if (ModeAnim.AnimMode == 4) {
			return ModeAnim.Frame == ModeAnim.PrevFrame;
		}
	}
	return false;
}

